"""Generate reviewable PostgreSQL DDL without connecting to any database."""

import argparse
from pathlib import Path

from sqlalchemy.dialects import postgresql
from sqlalchemy.schema import AddConstraint, CreateIndex, CreateTable

from lotuspond.models import Base
from lotuspond.schema_version import SCHEMA_VERSION


def render() -> str:
    dialect = postgresql.dialect()
    parts = [
        "-- Generated by backend/export_schema.py; do not edit by hand.",
        "-- For review and independently authorized initialization of a NEW EMPTY database only.",
        "-- This file is not an upgrade or reset script. It has never been applied to a hosted database.",
        "BEGIN;",
        "SELECT pg_advisory_xact_lock(736183);",
        "DO $$ BEGIN IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_type = 'BASE TABLE') THEN RAISE EXCEPTION 'Schema is not empty; initialization refused'; END IF; END $$;",
    ]
    for table in Base.metadata.sorted_tables:
        parts.append(str(CreateTable(table).compile(dialect=dialect)).strip() + ";")
    deferred_constraints = sorted(
        (
            constraint
            for table in Base.metadata.sorted_tables
            for constraint in table.foreign_key_constraints
            if constraint.use_alter
        ),
        key=lambda constraint: constraint.name,
    )
    parts.extend(
        str(AddConstraint(constraint).compile(dialect=dialect)) + ";"
        for constraint in deferred_constraints
    )
    indexes = sorted(
        (index for table in Base.metadata.sorted_tables for index in table.indexes),
        key=lambda index: index.name,
    )
    parts.extend(str(CreateIndex(index).compile(dialect=dialect)) + ";" for index in indexes)
    parts.extend(
        [
            f"INSERT INTO schema_version (version, installed_at) VALUES ({SCHEMA_VERSION}, CURRENT_TIMESTAMP);",
            "COMMIT;",
        ]
    )
    return "\n".join(line.rstrip() for line in "\n\n".join(parts).splitlines()) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    destination = Path(__file__).with_name("schema.sql")
    rendered = render()
    if args.check:
        if not destination.is_file() or destination.read_text() != rendered:
            raise SystemExit(
                "The SQL snapshot differs from the authoritative model. Regenerate and review it."
            )
    else:
        destination.write_text(rendered)
        print("Generated backend/schema.sql without connecting to a database.")


if __name__ == "__main__":
    main()
